\section{Entropy on finite uniform spaces}

A sample space is a finite set $S$ with the uniform measure; random variables are functions on $S$; logarithms are base $2$.

\begin{definition}
For nonempty $S$ and $g:S\to B$,
\[
H_S(g)=-\sum_{b\in g(S)}\frac{|g^{-1}(b)|}{|S|}\log_2\frac{|g^{-1}(b)|}{|S|}
=\log_2|S|-\frac1{|S|}\sum_{x\in S}\log_2|\{y\in S: g(y)=g(x)\}|,
\]
and $H_\emptyset(g)=0$. For $k:S\to C$,
\[
H_S(g\mid k)=\sum_{c\in k(S)}\frac{|k^{-1}(c)|}{|S|}H_{k^{-1}(c)}(g),\qquad I_S(g;k)=H_S(g)-H_S(g\mid k).
\]
\end{definition}

\section{Structural lemmas}

\begin{lemma}[Averaging form]
$H_S(g\mid k)=\frac1{|S|}\sum_{x\in S}H_{\{y:k(y)=k(x)\}}(g)$.
\end{lemma}

\begin{lemma}[Entropy sees only shapes]\label{lem:shape}
If $S_1,S_2$ are nonempty and $|\{x\in S_1:g(x)=t\}|\,|S_2|=|\{x\in S_2:g(x)=t\}|\,|S_1|$ for all $t$, then $H_{S_1}(g)=H_{S_2}(g)$.
\end{lemma}

\begin{lemma}[Conditional uniformity]\label{lem:condunif}
Let $R:S\to C$, $c:C\to D$. If for every $x\in S$ the $g$-count vector on $\{R=R(x)\}$ is proportional to that on $\{c\circ R=c(R(x))\}$, then $H_S(g\mid R)=H_S(g\mid c\circ R)$ and $I_S(g;R)=I_S(g;c\circ R)$.
\end{lemma}
\begin{proof}
Both conditional entropies are averages of cell entropies (averaging form), and the two cells through each $x$ have equal entropy by Lemma~\ref{lem:shape}.
\end{proof}

\begin{lemma}[Balanced covers are invisible]\label{lem:cover}
If $\pi:S\to U$ has all fibres of size $K>0$, then for all $f,h$ on $U$: $H_S(f\circ\pi)=H_U(f)$, $H_S(f\circ\pi\mid h\circ\pi)=H_U(f\mid h)$, and $I_S(f\circ\pi;h\circ\pi)=I_U(f;h)$.
\end{lemma}
\begin{proof}
Every count on $S$ of a pulled-back event is $K$ times the count on $U$, and $|S|=K|U|$; apply cellwise for the conditional statement.
\end{proof}

\begin{lemma}[Constant read-outs]\label{lem:const}
$H_S(g\mid\mathrm{const})=H_S(g)$, so $I_S(g;\mathrm{const})=0$.
\end{lemma}

\begin{lemma}[Deterministic read-outs]\label{lem:func}
If $k=\varphi\circ g$ on $S$, then $I_S(g;k)=H_S(k)$.
\end{lemma}
\begin{proof}
Inside a cell of $k$ the $g$-fibres are global $g$-fibres. Writing $H_S(g)$ and $H_S(g\mid k)$ in the second form of the definition, the $\log_2|g\text{-fibre}|$ terms cancel, leaving $H_S(k)$.
\end{proof}

\section{The fibre-product law}

Let $K/\Q$ be Galois with group $G$ and $m$ a conductor. For $p\nmid m\,\mathrm{disc}(K)$, Chebotarev in $K(\zeta_m)$ shows that $(p\bmod m,\Frob_p)$ is equidistributed on
\[
\F=\{(a,g)\in(\Z/m)^\times\times G:\chi(a)=\sigma(g)\},
\]
where $\sigma,\chi$ are restrictions to $Q=\mathrm{Gal}((K\cap\Q(\zeta_m))/\Q)$. Abstractly, $U$ is any finite residue set, $\chi:U\to Q$, $\sigma:G\to Q$, and $\F(U,\chi,\sigma)$ carries the uniform law.

\begin{definition}
The model is \emph{balanced with multiplicity $K$} if $|\{a\in U:\chi(a)=\sigma(g)\}|=K>0$ for all $g\in G$.
\end{definition}

\begin{theorem}[Fibre-product law]\label{thm:fibre}
For every $T:G\to B$, in a balanced model,
\[
I_{\F}(T(g);a)=I_G(T;\sigma),
\]
independently of $m$, $U$ and $K$.
\end{theorem}
\begin{proof}
\emph{Step 1.} For $(a,g)\in\F$, the fine cell $\{a'=a\}$ is in bijection with $\sigma^{-1}(\chi(a))$, while the coarse cell $\{\chi(a')=\chi(a)\}$ equals $\chi^{-1}(\chi(a))\times\sigma^{-1}(\chi(a))$ with first factor of size $K$. Counts are proportional, so Lemma~\ref{lem:condunif} gives $I_\F(T(g);a)=I_\F(T(g);\chi(a))$.
\emph{Step 2.} On $\F$, $\chi(a)=\sigma(g)$.
\emph{Step 3.} The projection $(a,g)\mapsto g$ is a balanced $K$-to-one cover; Lemma~\ref{lem:cover} gives $I_\F(T(g);\sigma(g))=I_G(T;\sigma)$.
\end{proof}

\section{The group $D_5$}

Let $D_5=\langle r,s\mid r^5=s^2=1,\ srs^{-1}=r^{-1}\rangle$ act on the five roots as on the vertices of a pentagon.

\begin{definition}
$T(g)$ is the cycle type of $g$: $1^5$ (identity), $5$ (four rotations), $1\cdot 2^2$ (five reflections). The sign $\sigma:D_5\to\Z/2$ maps rotations to $0$, reflections to $1$.
\end{definition}

\begin{proposition}\label{prop:ab}
(a) $T(g)$ faithfully encodes $\mathrm{ord}(g)\in\{1,5,2\}$. (b) $\sigma$ is a homomorphism. (c) Every homomorphism $\varphi$ from $D_5$ to a commutative group kills the rotations and equals $\varphi(s)$ on reflections; i.e.\ $D_5^{\mathrm{ab}}\cong\Z/2$.
\end{proposition}
\begin{proof}
For (c): $\varphi(r)^{-1}=\varphi(srs^{-1})=\varphi(r)$, so $\varphi(r)^2=1=\varphi(r)^5$, whence $\varphi(r)=1$.
\end{proof}

\begin{theorem}[Exact $D_5$ entropies]\label{thm:d5}
With the uniform law on $D_5$: $H(T)=\tfrac15+\tfrac12\log_2 5$, $H(\sigma)=1$, $I(T;\sigma)=1$, and $H(T\mid\sigma)=\tfrac12\log_2 5-\tfrac45$.
\end{theorem}
\begin{proof}
Densities $\tfrac1{10},\tfrac4{10},\tfrac5{10}$ give $H(T)$. The sign is balanced $5{:}5$. As $\sigma$ is a function of $T$, Lemma~\ref{lem:func} gives $I=H(\sigma)=1$. Directly, the rotation cell has law $(\tfrac15,\tfrac45)$ with entropy $\log_2 5-\tfrac85$ and the reflection cell has entropy $0$.
\end{proof}

\begin{theorem}[Quantization]\label{thm:quant}
For every homomorphism $\varphi$ from $D_5$ to a commutative group, $I(T;\varphi)\in\{0,1\}$.
\end{theorem}
\begin{proof}
By Proposition~\ref{prop:ab}(c), $\varphi$ is constant (then $I=0$ by Lemma~\ref{lem:const}) or an injective relabelling of $\sigma$ (then $I=1$).
\end{proof}

\begin{remark}
Non-homomorphic read-outs are not quantized: the indicator of the identity carries $\approx 0.469$ bit, but is invisible to every residue by Theorem~\ref{thm:fibre}.
\end{remark}

\begin{theorem}[The $D_5$ dial at every conductor]\label{thm:univ}
If $\chi:U\to\Z/2$ takes each value exactly $K>0$ times, then $I_{\F(U,\chi,\sigma)}(T(g);a)=1$.
\end{theorem}

Let $U_{320}$ be the $128$ reduced residues modulo $320$, and $\chi_{-10}$ the additive quadratic character of $\Q(\sqrt{-10})$: $\chi_{-10}(a)=0$ iff $a\bmod 40\in\{1,7,9,11,13,19,23,37\}$. Let $\chi_5(a)=0$ iff $a\equiv\pm1\pmod 5$.

\begin{lemma}[Dirichlet balance at $320$]
Each value of $\chi_{-10}$, and each value of $\chi_5$, is taken by exactly $64$ elements of $U_{320}$.
\end{lemma}

\begin{corollary}[The $D_5$ dial is measured]
For a $D_5$ field with quadratic subfield $\Q(\sqrt{-10})$, in the Chebotarev model, $I(p\bmod 320;T)=1$. The same holds with $\chi_5$.
\end{corollary}

\begin{remark}
The quintic $f(x)=x^5-5x+12$ has discriminant $2^{12}5^6$ and Galois group $D_5$; its type mod $p$ is determined by the number of roots ($5,0,1$). For all $33{,}857$ primes $7\le p<400{,}000$, $f$ has exactly one root mod $p$ iff $\chi_{-10}(p)=1$.
\end{remark}

\section{The semiprime channel}

For $N=pq$, multiplicativity gives $\chi(N)=\sigma(\Frob_p)+\sigma(\Frob_q)$ additively, so the model is the fibre product over $G\times G$ with $\sigma_2(g,h)=\sigma(g)+\sigma(h)$.

\begin{theorem}[Semiprime pair channel]
On $D_5\times D_5$: $H(T\times T)=2(\tfrac15+\tfrac12\log_2 5)\approx 2.72$, $H(\sigma_2)=1$, $I(T\times T;\sigma_2)=1$, and $H(T\times T\mid\sigma_2)=\log_2 5-\tfrac35$. Hence for every balanced residue model, in particular at $m^\ast=320$ with $\chi_{-10}$,
\[
I(N\bmod 320;(T(p),T(q)))=1=I(p\bmod 320;T).
\]
\end{theorem}
\begin{proof}
Entropy is additive over independent coordinates; $\sigma_2$ is a function of the pair and a fair coin; apply Lemma~\ref{lem:func} and Theorem~\ref{thm:fibre} on $G\times G$.
\end{proof}

The single bit is the parity of reflections, i.e.\ the Kronecker symbol $\left(\frac{-40}{N}\right)$, already computable from $N$.

\section{Dihedral groups}

\begin{theorem}[Odd dihedral one-bit law]
If $n$ is odd and $T=\mathrm{ord}$ on $D_n$, then $I(T;\sigma)=1$, and hence $I(p\bmod m;T)=1$ for every balanced residue model over the sign.
\end{theorem}
\begin{proof}
Rotations have odd order and reflections order $2$, so $\sigma$ is a function of $T$; $\sigma$ is balanced $n{:}n$, so $H(\sigma)=1$.
\end{proof}

\begin{theorem}[Parity is essential]
For $D_2$ with $T=\mathrm{ord}$, $I(T;\sigma)=\tfrac32-\tfrac34\log_2 3\approx 0.311$.
\end{theorem}
\begin{proof}
Orders $1,2,2,2$ give $H(T)=2-\tfrac34\log_2 3$; the rotation cell has entropy $1$, the reflection cell $0$, so $H(T\mid\sigma)=\tfrac12$.
\end{proof}

Numerically, for $n=4,6,\dots,14$ and $T=\mathrm{ord}$, $I=0.549,0.655,0.717,0.758,0.788,0.811$; with $T$ the vertex cycle type, $I=0.656,0.730,0.774,0.805,0.827,0.845$.

\section{Measurement versus theory}

\begin{proposition}
Using $\tfrac{202}{87}<\log_2 5<\tfrac{137}{59}$: the measured $H(T)=1.3517$ is below theory by an amount in $(0.0092,0.0094)$; the measured within-class entropy $0.3463$ is below theory by an amount in $(0.0146,0.0148)$; and $1.0054=1.3517-0.3463$ exceeds $1$ by $0.0054$.
\end{proposition}

The generic first-order plug-in bias $(\varphi(m)-1)(|T|-1)/(2M\ln 2)=127/(M\ln 2)$ equals $0.0054$ at $M\approx 33{,}900$. In the fibre-product model only $64$ residues admit two types, so counting occupied cells predicts about $(64-2)/(2M\ln2)\approx 0.0013$ at $M=33{,}857$. A fresh count with $f=x^5-5x+12$ over $7\le p<400{,}000$ gives $\hat H(T)=1.3614$, $\hat H(T\mid p\bmod 320)=0.3604$, $\hat I=1.0010$; for $300{,}000$ random $N=pq$, $\hat I(N\bmod 320;\text{pair})=1.0011$.

\section{Algorithms}

\begin{algorithm}[Exact dial]
Tally $c(t,q)=|\{g:T(g)=t,\sigma(g)=q\}|$ and return $H(T)-\sum_q\frac{c(\cdot,q)}{|G|}H(c(\cdot,q))$. Cost $O(|G|)$; by Theorem~\ref{thm:fibre} this is the residue dial at every balanced conductor.
\end{algorithm}

\begin{algorithm}[Empirical dial]
For each prime $p\le X$, compute $x^p\bmod(f,p)$ by repeated squaring, set $r(p)=\deg\gcd(f,x^p-x)$, map $r=5,0,1$ to $1^5,5,1\cdot2^2$, and return the plug-in $\hat I$ of the table $(T(p),p\bmod m)$. Cost $O(\pi(X)\log X)$ operations in $\mathbb F_p[x]/(f)$.
\end{algorithm}

\section{Open problems}

\begin{conjecture}[Abelianization dial law]
For every finite Galois group $G$ and class function $T$, $\sup_m I(p\bmod m;T)=I_G(T;\pi_{\mathrm{ab}})$ with $\pi_{\mathrm{ab}}:G\to G^{\mathrm{ab}}$.
\end{conjecture}

\begin{conjecture}[Even dihedral deficit]
For even $n$ and $T$ the vertex cycle type on $D_n$, $I<1$ and $1-I\to0$ as $n\to\infty$.
\end{conjecture}

\begin{conjecture}[Semiprime pair collapse]
If $\sigma:G\to Q$ with $Q$ elementary abelian of exponent $2$ and $\sigma$ a function of $T$, the semiprime channel equals $H(\sigma(p)+\sigma(q))$; it equals the prime channel whenever $\sigma$ is balanced.
\end{conjecture}

\begin{conjecture}[Plug-in dial bias]
$\mathbb E[\hat I]-I$ has an expansion in $1/M$ whose leading coefficient is determined by the occupied cells of the fibre product, with $(\varphi(m)-1)(|T|-1)/(2M\ln 2)$ as the fully occupied envelope.
\end{conjecture}

\end{document}

