#!/usr/bin/env python3
"""The dihedral dial: exactly one bit for odd n, a deficit for even n."""
from __future__ import annotations
import math
from collections import Counter
from typing import Hashable, List, Sequence, Tuple
import matplotlib.pyplot as plt

def entropy(xs: Sequence[Hashable]) -> float:
    n = len(xs)
    return -sum(c / n * math.log2(c / n) for c in Counter(xs).values())

def mutual_info(pairs: Sequence[Tuple[Hashable, Hashable]]) -> float:
    cells: dict = {}
    for x, y in pairs:
        cells.setdefault(y, []).append(x)
    n = len(pairs)
    return entropy([x for x, _ in pairs]) - sum(len(c) / n * entropy(c) for c in cells.values())

def elements(n: int) -> List[Tuple[int, int]]:
    return [(k, e) for e in (0, 1) for k in range(n)]

def order(n: int, g: Tuple[int, int]) -> int:
    k, e = g
    return 2 if e else n // math.gcd(k, n)

def cycle_type(n: int, g: Tuple[int, int]) -> Tuple[int, ...]:
    k, e = g
    perm = [(k + v) % n if e == 0 else (k - v) % n for v in range(n)]
    seen, out = [False] * n, []
    for v in range(n):
        if not seen[v]:
            L, w = 0, v
            while not seen[w]:
                seen[w], w, L = True, perm[w], L + 1
            out.append(L)
    return tuple(sorted(out))

def main() -> None:
    ns = list(range(2, 41))
    i_ord = [mutual_info([(order(n, g), g[1]) for g in elements(n)]) for n in ns]
    i_cyc = [mutual_info([(cycle_type(n, g), g[1]) for g in elements(n)]) for n in ns]
    fig, ax = plt.subplots(figsize=(9, 4.5))
    ax.axhline(1, color="gray", ls="--", lw=1)
    ax.plot(ns, i_ord, "o-", label="T = order of Frobenius")
    ax.plot(ns, i_cyc, "s-", ms=4, label="T = cycle type on n-gon vertices")
    ax.annotate("D2: 3/2 - (3/4) log2 3 = 0.311", (2, i_ord[0]), (6, 0.2),
                arrowprops=dict(arrowstyle="->"))
    ax.annotate("D5: exactly 1 bit", (5, 1), (9, 1.05), arrowprops=dict(arrowstyle="->"))
    ax.set_xlabel("n (dihedral group D_n of order 2n)")
    ax.set_ylabel("I(sign ; T)  [bits]")
    ax.set_ylim(-0.05, 1.12)
    ax.set_title("Odd polygons read exactly one bit; even polygons fall short")
    ax.legend()
    plt.tight_layout()
    plt.savefig("dihedral_dial.png", dpi=150)
    plt.show()

if __name__ == "__main__":
    main()

